sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var requestBody = request.body.data;
    var results = [];
    var successCount = 0;
    var errorCount = 0;

    try {
        // Validate request structure
        if (!requestBody.employees || !Array.isArray(requestBody.employees)) {
            response.setStatus(400);
            response.setBody({
                "error": "Invalid request format",
                "message": "Request must contain an 'employees' array",
                "example": {
                    "employees": [
                        {
                            "employee_id": "WD001234",
                            "email": "john.doe@company.com",
                            "first_name": "John",
                            "last_name": "Doe"
                        }
                    ]
                }
            });
            return;
        }

        gs.info('Workday Batch Integration: Processing ' + requestBody.employees.length + ' employees');

        // Process each employee
        for (var i = 0; i < requestBody.employees.length; i++) {
            var employeeData = requestBody.employees[i];
            var result = {
                "index": i,
                "employee_id": employeeData.employee_id,
                "email": employeeData.email
            };

            try {
                // Validate required fields for this employee
                if (!employeeData.employee_id || !employeeData.email) {
                    result.success = false;
                    result.error = "Missing required fields (employee_id and email)";
                    errorCount++;
                    results.push(result);
                    continue;
                }

                // Check if user already exists
                var userRecord = new GlideRecord('sys_user');
                var userExists = false;

                // Check by employee_id first
                userRecord.addQuery('employee_number', employeeData.employee_id);
                userRecord.query();
                if (userRecord.next()) {
                    userExists = true;
                } else {
                    // Check by email
                    userRecord = new GlideRecord('sys_user');
                    userRecord.addQuery('email', employeeData.email);
                    userRecord.query();
                    if (userRecord.next()) {
                        userExists = true;
                    }
                }

                // If user doesn't exist, create new record
                if (!userExists) {
                    userRecord = new GlideRecord('sys_user');
                    userRecord.initialize();
                }

                // Map fields
                if (employeeData.employee_id) {
                    userRecord.setValue('employee_number', employeeData.employee_id);
                    if (!employeeData.username) {
                        userRecord.setValue('user_name', employeeData.employee_id);
                    }
                }

                if (employeeData.email) {
                    userRecord.setValue('email', employeeData.email);
                }

                if (employeeData.username) {
                    userRecord.setValue('user_name', employeeData.username);
                }

                if (employeeData.first_name) {
                    userRecord.setValue('first_name', employeeData.first_name);
                }

                if (employeeData.last_name) {
                    userRecord.setValue('last_name', employeeData.last_name);
                }

                if (employeeData.title || employeeData.job_title) {
                    userRecord.setValue('title', employeeData.title || employeeData.job_title);
                }

                if (employeeData.department) {
                    var deptRecord = new GlideRecord('cmn_department');
                    deptRecord.addQuery('name', employeeData.department);
                    deptRecord.query();
                    if (deptRecord.next()) {
                        userRecord.setValue('department', deptRecord.sys_id);
                    }
                }

                if (employeeData.location) {
                    var locationRecord = new GlideRecord('cmn_location');
                    locationRecord.addQuery('name', employeeData.location);
                    locationRecord.query();
                    if (locationRecord.next()) {
                        userRecord.setValue('location', locationRecord.sys_id);
                    }
                }

                if (employeeData.phone || employeeData.work_phone) {
                    userRecord.setValue('phone', employeeData.phone || employeeData.work_phone);
                }

                if (employeeData.mobile_phone) {
                    userRecord.setValue('mobile_phone', employeeData.mobile_phone);
                }

                if (employeeData.start_date || employeeData.hire_date) {
                    var startDate = employeeData.start_date || employeeData.hire_date;
                    userRecord.setValue('u_start_date', startDate);
                }

                // Handle manager assignment
                if (employeeData.manager_employee_id) {
                    var managerRecord = new GlideRecord('sys_user');
                    managerRecord.addQuery('employee_number', employeeData.manager_employee_id);
                    managerRecord.query();
                    if (managerRecord.next()) {
                        userRecord.setValue('manager', managerRecord.sys_id);
                    }
                } else if (employeeData.manager_email) {
                    var managerRecord = new GlideRecord('sys_user');
                    managerRecord.addQuery('email', employeeData.manager_email);
                    managerRecord.query();
                    if (managerRecord.next()) {
                        userRecord.setValue('manager', managerRecord.sys_id);
                    }
                }

                userRecord.setValue('active', true);

                if (!userExists) {
                    userRecord.setValue('user_type', 'employee');
                }

                // Save the record
                var userSysId;
                if (userExists) {
                    userSysId = userRecord.update();
                    result.action = "updated";
                } else {
                    userSysId = userRecord.insert();
                    result.action = "created";

                    // Add default role for new employees
                    if (userSysId) {
                        var userRoleRecord = new GlideRecord('sys_user_has_role');
                        userRoleRecord.initialize();
                        userRoleRecord.setValue('user', userSysId);

                        var roleRecord = new GlideRecord('sys_user_role');
                        roleRecord.addQuery('name', 'x_58872_needit.needit_user');
                        roleRecord.query();
                        if (roleRecord.next()) {
                            userRoleRecord.setValue('role', roleRecord.sys_id);
                            userRoleRecord.insert();
                        }
                    }
                }

                if (userSysId) {
                    result.success = true;
                    result.user_sys_id = userSysId;
                    successCount++;
                } else {
                    result.success = false;
                    result.error = "Failed to save user record";
                    errorCount++;
                }

            } catch (employeeError) {
                result.success = false;
                result.error = "Error processing employee: " + employeeError.message;
                errorCount++;
                gs.error('Workday Batch Integration - Employee Error: ' + employeeError.message + ' for employee ID: ' + employeeData.employee_id);
            }

            results.push(result);
        }

        // Return batch results
        response.setStatus(200);
        response.setBody({
            "success": true,
            "message": "Batch processing completed",
            "summary": {
                "total_processed": requestBody.employees.length,
                "successful": successCount,
                "errors": errorCount
            },
            "results": results
        });

    } catch (error) {
        gs.error('Workday Batch Integration Error: ' + error.message);
        response.setStatus(500);
        response.setBody({
            "error": "Internal server error",
            "message": "An unexpected error occurred during batch processing",
            "details": error.message
        });
    }

})(request, response);
